export function demoReport(scenario) {
  const raw = RAW[scenario.id];
  if (!raw) return null;
  const conv = { turns: scenario.turns, map: { [scenario.roles[0]]: 'A', [scenario.roles[1]]: 'B' } };
  const { value, log } = checkStage2(raw, conv);
  return { result: value, log, turns: scenario.turns, map: conv.map };
}
